/// A pubspec that asks for nothing from the Flutter SDK.
const String plainPubspec = '''
name: html_to_markdown_ffi
version: 1.2.4

environment:
  sdk: ^3.11.0

dependencies:
  ffi: ^2.1.0
  html_to_markdown_ffi_platform: ^1.2.4

flutter:
  plugin:
    platforms:
      android:
        default_package: html_to_markdown_ffi_android
''';

/// A pubspec that constrains the Flutter SDK in its `environment:`.
const String environmentConstrainedPubspec = '''
name: html_to_markdown_ffi
version: 1.2.4

environment:
  sdk: ^3.11.0
  flutter: ">=3.41.0"

dependencies:
  ffi: ^2.1.0
''';

/// A pubspec that depends on the Flutter SDK.
const String sdkDependentPubspec = '''
name: html_to_markdown_ffi
version: 1.2.4

environment:
  sdk: ^3.11.0

dependencies:
  flutter:
    sdk: flutter
  ffi: ^2.1.0
''';

/// A pubspec whose block is indented with tabs.
const String tabIndentedPubspec = 'name: html_to_markdown_ffi\n'
    'version: 1.2.4\n'
    '\n'
    'environment:\n'
    '\tsdk: ^3.11.0\n'
    '\tflutter: ">=3.41.0"\n'
    '\n'
    'dependencies:\n'
    '\tffi: ^2.1.0\n';

/// A pubspec whose `flutter` dependency is a hosted package, next to a
/// sibling dependency that happens to be an SDK package.
const String hostedFlutterPubspec = '''
name: html_to_markdown_ffi
version: 1.2.4

environment:
  sdk: ^3.11.0

dependencies:
  flutter:
    hosted: https://pub.dev
    version: ^1.0.0
  package:
    sdk: flutter
''';

/// A manifest that is not YAML at all.
const String malformedPubspec = 'name: html_to_markdown_ffi\nfoo: [1, 2\n';

void main() {
  group('A1 (AC-1)', () {
    test('A1 — the resolution succeeds: no family member in the graph demands the Flutter SDK, neither as an `environment: flutter:` constraint nor as a `flutter: sdk: flutter` dependency.', () {
      final Object? result = (() {
