        } on UnimplementedError catch (error) {
          return error;
        }
      })();
      expect(result, isNot(isA<UnimplementedError>()));
      // The observable outcome of the scenario: no member of the shipped
      // family asks a pure-Dart consumer for the Flutter SDK.
      expect(subject.subject_a1(), isEmpty);
    });

    test('A1 — a member that constrains the Flutter SDK is reported', () {
      final fixture = Fixture.create();
      addTearDown(fixture.dispose);
      for (final packageName in familyPackages) {
        fixture.write('packages/$packageName/pubspec.yaml', plainPubspec);
      }
      fixture.write(
        'packages/html_to_markdown_ffi/pubspec.yaml',
        environmentConstrainedPubspec,
      );

      final violations = subject.subject_a1(
        layout: RepoLayout(fixture.root),
      );

      expect(violations, hasLength(1));
      expect(
        violations.single,
        'html_to_markdown_ffi constrains the Flutter SDK in its '
        '`environment:` — a consumer with a plain Dart SDK cannot resolve '
        'it.',
      );
    });

    test('A1 — a member that depends on the Flutter SDK is reported', () {
      final fixture = Fixture.create();
      addTearDown(fixture.dispose);
      for (final packageName in familyPackages) {
        fixture.write('packages/$packageName/pubspec.yaml', plainPubspec);
      }
      fixture.write(
        'packages/html_to_markdown_ffi_macos/pubspec.yaml',
        sdkDependentPubspec,
      );

      final violations = subject.subject_a1(
        layout: RepoLayout(fixture.root),
      );

      expect(violations, hasLength(1));
      expect(
        violations.single,
        'html_to_markdown_ffi_macos depends on the Flutter SDK — a consumer '
        'with a plain Dart SDK cannot resolve it.',
      );
    });

    test('A1 — the plugin manifest is not mistaken for a requirement', () {
      final manifest = subject.Pubspec.parse(plainPubspec)!;

      expect(manifest.constrainsFlutterSdk, isFalse);
      expect(manifest.dependsOnFlutterSdk, isFalse);
